insert into legal_calculation_policy_link (id, article_id, policy_id, policy_code, legal_basis_kind, required_variables, required_evidence, variable_rules, notes) select gen_random_uuid(), la.id, cp.id, 'DEF_COST_COMPONENT_ROLLUP_V1', 'primary', '["source_cell", "target_component"]'::jsonb, '["source_workbook_cell", "legal_article"]'::jsonb, '{"source_policy_code": "P001", "excel_formula_template": "<외부참조>", "example": "집계표!E19", "occurrence": 8}'::jsonb, 'Excel 시트 간 rollup lookup. 원가 구성요소와 총액 구성에 해당.' from legal_article la left join calculation_policy cp on cp.policy_code = 'P001' where la.article_no = '제6조' and la.is_supplementary = false on conflict (article_id, policy_code, legal_basis_kind) do nothing;
